            // TODO API_TEST_START
            net.coobird.thumbnailator.builders.ThumbnailParameterBuilder builder = new net.coobird.thumbnailator.builders.ThumbnailParameterBuilder();
            builder.size(50, 50);
            net.coobird.thumbnailator.ThumbnailParameter param = builder.build();

            net.coobird.thumbnailator.tasks.io.BufferedImageSource source = new net.coobird.thumbnailator.tasks.io.BufferedImageSource(sourceImage);
            net.coobird.thumbnailator.tasks.io.BufferedImageSink sink = new net.coobird.thumbnailator.tasks.io.BufferedImageSink();

            net.coobird.thumbnailator.tasks.SourceSinkThumbnailTask<java.awt.image.BufferedImage, java.awt.image.BufferedImage> task = 
                new net.coobird.thumbnailator.tasks.SourceSinkThumbnailTask<>(param, source, sink);

            net.coobird.thumbnailator.tasks.io.ImageSink<java.awt.image.BufferedImage> dest = task.getDestination();

            assert dest == sink : "getDestination must return the exact ImageSink instance passed to the task";
            System.out.println("__CHECK__ getDestination " + dest.getClass().getSimpleName());
            // TODO API_TEST_END
            System.out.println("__DONE__");
        } catch (Throwable exc) {
            System.err.println("__RUN_ERR__ " + exc.getClass().getSimpleName()
                    + ": " + exc.getMessage());
            exc.printStackTrace(System.err);
            System.exit(1);
        }
